contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address target) public {
        // Restrict amount to contract balance to avoid arithmetic issues, but keep wide.
        vm.assume(amount <= address(c).balance);
        // Deploy an adversarial helper that reverts on receiving Ether.
        Reverter reverter = new Reverter();
        address adversary = address(reverter);
        // Non-owner calls sendMoney with the adversarial target.
        address nonOwner = address(0xdead);
        vm.prank(nonOwner);
        bool ok = true;
        try c.sendMoney(adversary, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The correct contract must succeed (owner pranked automatically by setUp? No, owner is msg.sender of setUp, but we prank nonOwner, so it must revert because onlyOwner).
        // Actually, onlyOwner requires msg.sender == owner. With nonOwner, it should revert.
        // Wait, the property is about the reference holding for all inputs. The buggy version passes onlyOwner(true) so nonOwner can call sendMoney and it will revert because Reverter reverts.
        // The reference: nonOwner cannot call sendMoney -> it reverts. So both revert? No.
        // The difference: After a call to sendMoney completes, withdrawAll differs.
        // We need a rule that the reference satisfies and the bug breaks.
        // Rule: For any amount and any target, a non-owner calling sendMoney must revert.
        // Reference: reverts (onlyOwner fails). Buggy: may succeed if target accepts Ether, or revert if target reverts. But the rule "must revert" is true for reference, but buggy might succeed or revert. So bug violates "must revert" because it can succeed.
        // Let's assert that the non-owner call reverts.
        // But the assertion is about the reference holding for all admissible inputs. The reference indeed reverts for any input if caller is non-owner. So assert that ok is false.
        assertTrue(!ok);
    }
}
