pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // Ensure caller is not the null address
        vm.assume(caller != address(0));
        // Ensure amount is non-zero and within contract balance after funding
        vm.assume(amount > 0);
        // Fund the contract so withdraw can work
        uint256 contractFunding = amount + 1 ether;
        vm.deal(address(this), contractFunding);
        (bool fundSuccess,) = address(c).call{value: contractFunding}("");
        require(fundSuccess, "fund failed");
        // Fund caller to pay for gas; give extra 1 ether for gas buffer
        vm.deal(caller, 1 ether);
        // Record balances before withdraw
        uint256 callerBalanceBefore = caller.balance;
        uint256 contractBalanceBefore = address(c).balance;
        // Execute withdraw as the caller (non-owner in general; address(this) may be owner but caller is fuzzed)
        vm.prank(caller);
        // Wrap in try/catch to handle revert cases gracefully
        bool success;
        try c.withdraw(amount) {
            success = true;
        } catch {
            success = false;
        }
        uint256 callerBalanceAfter = caller.balance;
        uint256 contractBalanceAfter = address(c).balance;
        // If withdraw succeeded, the contract's balance must have decreased by exactly amount.
        // If it failed, balances must remain unchanged.
        // The buggy version sends funds to the owner instead of the caller, so when a non-owner caller withdraws,
        // the contract balance decreases but the caller does not receive the funds (balance unchanged apart from gas).
        // This assertion checks: if success, contract balance drops by amount AND caller's balance does NOT decrease.
        // For correct contract, caller's balance increases by amount; for buggy, caller's balance stays (or decreases due to gas)
        // but definitely does not increase. We check: if success, caller's balance change == amount (for correct, increase;
        // for buggy, no increase, so callerBalanceAfter < callerBalanceBefore + amount).
        // To cover both, we assert: if success then callerBalanceAfter >= callerBalanceBefore (no net decrease despite gas expense? actually with gas it might slightly decrease. We need a robust rule.
        // Better rule: For the owner (msg.sender == owner), both P and M behave identically? No, P sends to msg.sender (owner) and M sends to owner, so same.
        // Difference: when caller != owner. For P: caller receives amount. For M: caller does not receive amount; owner receives.
        // So we need to ensure caller != owner; otherwise test cannot distinguish.
        // But we cannot hard-code caller != owner as assumption? We can assume caller != address(c.owner()) after fuzzing.
        // That is admissible.
        vm.assume(caller != address(c.owner()));
        // Re-assume after reading owner
        // Now for correct contract, if withdraw success, caller balance increases by amount.
        // For buggy, caller balance does not increase (or may even decrease due to gas, but no Ether transferred).
        // Assert: if success, callerBalanceAfter == callerBalanceBefore + amount (for correct) — bug fails because after < before + amount.
        // This is the property we check.
        if (success) {
            assertEq(callerBalanceAfter, callerBalanceBefore + amount, "caller should receive withdrawn amount");
        }
        // No assertion needed on failure — both must revert or succeed under same conditions.
    }
}

