import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address target) public {
        // Keep amount admissible: non-zero and within balance we will provide
        vm.assume(amount > 0);
        address owner = c.owner();
        vm.deal(owner, amount);
        // Deploy an adversarial helper that always fails on receiving Ether
        Reverter reverter = new Reverter();
        // Record balance before the call
        uint256 balanceBefore = address(c).balance;
        bool success;
        // Wrap the sendMoney call to catch revert
        vm.prank(owner);
        try c.sendMoney(address(reverter), amount) {
            success = true;
        } catch {
            success = false;
        }
        uint256 balanceAfter = address(c).balance;
        // General rule: either the call succeeded and balance decreased by amount,
        // or it reverted and balance stayed the same. The mutant violates this by
        // not reverting on a failing external call, so it returns success=true while
        // balance stays unchanged (or decreases without actual transfer).
        assertTrue(
            (balanceBefore == balanceAfter && !success) ||
            (balanceAfter == balanceBefore - amount && success)
        );
    }
}

